// Normalizar el texto de entrada y el chat ID
const isVoice = $items('¿Es Audio de Voz?')[0].json.message.voice ? true : false;
let userText = '';
let chatId = '';

if (isVoice) {
  userText = $json.text || '';
  chatId = $items('¿Es Audio de Voz?')[0].json.message.chat.id;
} else {
  userText = $json.message.text || '';
  chatId = $json.message.chat.id;
}

return [{
  json: {
    chatId,
    userText,
    fechaActual: new Date().toISOString().split('T')[0],
    horaActual: new Date().toTimeString().slice(0, 5)
  }
}];

