// Extraer y formatear las herramientas a ejecutar en Postgres
const toolCalls = $json.choices[0].message.tool_calls || [];
const chatId = $items('Normalizar Entrada (Texto y ChatID)')[0].json.chatId;
const queries = [];

for (const tool of toolCalls) {
  const name = tool.function.name;
  const args = JSON.parse(tool.function.arguments || '{}');

  if (name === 'agendar_actividad') {
    const fecha = args.fecha || new Date().toISOString().split('T')[0];
    queries.push({
      action: 'agendar',
      query: `INSERT INTO agenda_diaria (fecha, hora, actividad) VALUES ('${fecha}', '${args.hora}', '${args.actividad.replace(/'/g, "''")}') RETURNING *;`
    });
  } else if (name === 'crear_habito') {
    const slug = args.nombre.toLowerCase().replace(/\s+/g, '-');
    queries.push({
      action: 'habito',
      query: `INSERT INTO habitos_config (slug, nombre, hora_disparo, pregunta_prompt) VALUES ('${slug}', '${args.nombre.replace(/'/g, "''")}', '${args.hora_disparo}', '${args.pregunta.replace(/'/g, "''")}') ON CONFLICT (slug) DO UPDATE SET hora_disparo = EXCLUDED.hora_disparo, pregunta_prompt = EXCLUDED.pregunta_prompt RETURNING *;`
    });
  }
}

return queries.map(q => ({ json: { ...q, chatId } }));
